import { useState } from "react";
import { db, auth } from "../../firebase";
import { collection, addDoc, Timestamp } from "firebase/firestore";
import { Button, Form, FormGroup, Label, Input } from "reactstrap";

const CarbonInput = () => {
  const [date, setDate] = useState("");
  const [category, setCategory] = useState("Diet");
  const [carbonEmission, setCarbonEmission] = useState(0);
  const [carbonCredits, setCarbonCredits] = useState(0);
  const [reductionProgress, setReductionProgress] = useState(0);
  const [rank, setRank] = useState("Bronze");

  const calculateCredits = (emission) => {
    return Math.max(0, (100 - emission) * 0.1);
  };

  const calculateRank = (credits) => {
    if (credits > 500) return "Gold";
    if (credits > 200) return "Silver";
    return "Bronze";
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!auth.currentUser) return;

    const creditsEarned = calculateCredits(carbonEmission);
    const updatedRank = calculateRank(creditsEarned);

    try {
      await addDoc(collection(db, "carbon_logs"), {
        userId: auth.currentUser.uid,
        date: Timestamp.fromDate(new Date(date)),
        category,
        carbonEmission,
        carbonCredits: creditsEarned,
        rank: updatedRank,
      });

      setCarbonCredits(creditsEarned);
      setReductionProgress(20); // Placeholder value for now
      setRank(updatedRank);
    } catch (error) {
      console.error("Error saving data: ", error);
    }
  };

  return (
    <Form onSubmit={handleSubmit}>
      <FormGroup>
        <Label for="date">Date</Label>
        <Input
          type="date"
          id="date"
          value={date}
          onChange={(e) => setDate(e.target.value)}
          required
        />
      </FormGroup>

      <FormGroup>
        <Label for="category">Category</Label>
        <Input
          type="select"
          id="category"
          value={category}
          onChange={(e) => setCategory(e.target.value)}
        >
          <option>Diet</option>
          <option>Transport</option>
          <option>Energy</option>
        </Input>
      </FormGroup>

      <FormGroup>
        <Label>Carbon Emission (kg CO₂)</Label>
        <Input type="text" value={carbonEmission} disabled />
      </FormGroup>

      <p>Carbon Credits Earned: {carbonCredits}</p>
      <p>Carbon Reduction Progress: {reductionProgress}%</p>
      <p>Rank: {rank}</p>

      <Button color="success" type="submit">Save Data</Button>
    </Form>
  );
};

export default CarbonInput;
